 void physicalControlsAboveIme()throws Exception{final android.graphics.Rect ime=new android.graphics.Rect();for(android.view.accessibility.AccessibilityWindowInfo window:m.getUiAutomation().getWindows())if(window.getType()==android.view.accessibility.AccessibilityWindowInfo.TYPE_INPUT_METHOD){window.getBoundsInScreen(ime);break;}m.check(ime.width()>0&&ime.height()>=100,"physical IME rectangle has substantial height");final boolean[] buttons={true},editable={false};m.runOnMainSync(()->{android.graphics.Rect frame=new android.graphics.Rect();m.activity.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);View root=m.activeDialogRoot();for(String name:new String[]{"Применить","Отмена"}){View button=v.button(root,name);if(button==null){buttons[0]=false;continue;}int[] xy=new int[2];button.getLocationOnScreen(xy);buttons[0]&=button.isShown()&&xy[0]>=frame.left&&xy[0]+button.getWidth()<=frame.right&&xy[1]>=frame.top&&xy[1]+button.getHeight()<=Math.min(frame.bottom,ime.top);}EditText field=field(root);if(field!=null){int[] xy=new int[2];field.getLocationOnScreen(xy);editable[0]=field.isShown()&&Math.min(xy[1]+field.getHeight(),Math.min(frame.bottom,ime.top))-Math.max(xy[1],frame.top)>=field.getLineHeight();}});m.check(buttons[0],"both vertex actions physically above IME and inside system frame");m.check(editable[0],"physical editable line visible above real IME");}
