 long route(Object store)throws Exception{long id=fixture.insert(store);Object d=r.load(store,id);Element feature=m.element(d,"point"),old=(Element)feature.getElementsByTagNameNS("*","Point").item(0);Document doc=feature.getOwnerDocument();Element line=doc.createElementNS(feature.getNamespaceURI(),"LineString"),coordinates=doc.createElementNS(feature.getNamespaceURI(),"coordinates");coordinates.setTextContent("10,20,30 11,21,31");line.appendChild(coordinates);feature.replaceChild(line,old);m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,d);return id;}
