 void foreign(Object store,boolean otherProject)throws Exception{long id=fixture.insert(store),other=-1;try{Object before=r.load(store,id);byte[] xml=r.xml(before);Map<String,byte[]> assets=new HashMap<>(m.assets(before));long target=id;if(otherProject){Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_VERTEX_FOREIGN");target=other;}open(id,mainText);final long pid=target;final String feature=otherProject?"point":"other";m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",pid).putExtra("feature",feature)));actualLand();m.check((Long)m.editorField("project")==target&&feature.equals(m.editorField("featureId"))&&m.editorField("vertexDraft")==null&&!state().getBoolean("present"),"foreign owner/feature never adopts raw vertex intent");m.check(m.geometryInput().equals(otherProject?"20 10 30":"22 12 32"),"foreign owner keeps its own main input");snapshot(otherProject?"vertex-foreign-project":"vertex-foreign-feature");m.check(Arrays.equals(xml,r.xml(r.load(store,id)))&&Arrays.equals(xml,r.xml(r.load(store,target))),"foreign guard keeps both documents intact");r.sameAssets(r.load(store,id),assets);r.sameAssets(r.load(store,target),assets);v.emit("VERTEX_FOREIGN project="+otherProject+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();boolean all=true;try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(String kind:new String[]{"valid","invalid"})all&=scenario(store,kind);m.check(all,"raw vertex form restored in both cases");writeRoute(store,false);reject(store,false);reject(store,true);writeRoute(store,true);foreign(store,true);foreign(store,false);m.check(m.requests.get()==requests,"raw vertex form makes no tile requests");m.check(all,"raw vertex form, cursor and error survive actual Activity recreation");}finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}}
